types.doc:
CCD, exactly three.js r187's CCDIKSolver.updateOne/update, on a pose:
- the target is the target bone's model position (or target_position
  when target < 0), read once per chain;
- links run in array order (r187: effector side first); a disabled link
  ends the pass;
- the angle is acos(clamp(dot)), computed as atan2(|cross|, dot) (the
  same angle; float acos near 1 would lose half its bits where three.js
  has doubles); turns under 1e-5 are skipped;
  min_angle / max_angle clamp the step; the rotation is about
  cross(effector, target) in the link's own frame, applied as
  link.quaternion * step;
- `limitation` projects the rotation onto that axis keeping its sign,
  then rotation_min / rotation_max clamp its XYZ Euler angles;
- the iterations stop early when no link turned;
- with a blend factor < 1 every link slerps from its incoming rotation.
Mapping from r187: ik.target -> target, ik.effector -> effector,
ik.links[j] -> links[j] (index, enabled: !disabled, limitation,
rotationMin, rotationMax), ik.iteration, ik.minAngle, ik.maxAngle,
ik.blendFactor.

types.decl:
typedef struct cw_ccdik_link {
  int index;
  bool disabled;         /* r187 enabled === false */
  bool has_limitation;
  t3_vec3 limitation;    /* unit axis in the link's frame */
  bool has_rotation_min, has_rotation_max;
  t3_vec3 rotation_min, rotation_max; /* XYZ Euler radians */
} cw_ccdik_link;

typedef struct cw_ccdik {
  int target;            /* bone index; < 0: target_position */
  t3_vec3 target_position;
  int effector;
  const cw_ccdik_link *links;
  int link_count;
  int iteration;         /* <= 0: 1 (r187 default) */
  bool has_min_angle, has_max_angle;
  float min_angle, max_angle;
  bool has_blend_factor;
  float blend_factor;    /* overrides the solve's blend for this chain */
} cw_ccdik;

typedef struct cw_ik_joint {
  cw_ik_joint_kind kind;
  t3_vec3 axis;          /* HINGE: axis in the parent bone's local frame */
  float half_angle;      /* CONE: radians */
} cw_ik_joint;

typedef struct cw_chain_opts {
  int max_iterations;    /* default 4 */
  float min_distance;    /* model units; default 0.001 */
  float weight;          /* blend with the incoming pose */
  const cw_ik_joint *joints; /* n entries or NULL; joints[0] is the root's own */
} cw_chain_opts;

typedef struct cw_foot_state {
  t3_vec3 ground;
  t3_vec3 normal;
  float offset;
  float lift;
  bool hit;
} cw_foot_state;

typedef enum {
  CW_BIND_NONE,
  CW_BIND_KEY,          /* code = SDL scancode */
  CW_BIND_MOUSE,        /* code = 0 left, 1 right, 2 middle */
  CW_BIND_WHEEL,        /* code = 0 vertical, 1 horizontal; dir +1 up/right, -1 down/left */
  CW_BIND_PAD_BUTTON,   /* code = cw_pad_button */
  CW_BIND_PAD_AXIS,     /* code = cw_pad_axis; dir +1 / -1; threshold */
  CW_BIND_TOUCH_BUTTON, /* code = touch control id */
  CW_BIND_TOUCH_STICK,  /* code = touch control id; dir 0 left, 1 right, 2 up, 3 down */
} cw_binding_kind;

typedef struct cw_binding {
  uint8_t kind;      /* cw_binding_kind */
  int8_t dir;
  uint16_t code;
  float threshold;   /* PAD_AXIS: deflection below this contributes 0 (0 = any) */
} cw_binding;

typedef enum {
  CW_DEADZONE_AXIAL,         /* each component on its own: |c| < dz -> 0, else rescaled dz..1 -> 0..1 */
  CW_DEADZONE_RADIAL,        /* length < dz -> (0,0), else the vector unchanged */
  CW_DEADZONE_SCALED_RADIAL, /* length < dz -> (0,0), else direction * rescaled length (smooth from 0) */
} cw_deadzone_mode;

typedef enum {
  CW_TOUCH_CORNER_AUTO,  /* a thumbstick's bottom left, a button's bottom right */
  CW_TOUCH_BOTTOM_LEFT,
  CW_TOUCH_BOTTOM_RIGHT,
  CW_TOUCH_TOP_LEFT,
  CW_TOUCH_TOP_RIGHT,
} cw_touch_corner;

typedef struct cw_touch_stick_desc {
  cw_touch_corner corner; /* where x, y are measured from (AUTO: bottom left) */
  float x, y;             /* home, touch units in from the corner; 0, 0 = 150, 140 */
  float radius;           /* full deflection at this distance from home, touch units; 0 = 70 */
  float zone;             /* touches starting between the corner and this far past home (each axis)
                           * belong to the stick, touch units; 0 = 2.4 * radius */
  bool floating;          /* the older feel: the ring centres where the touch started (in the zone) */
  bool hidden;            /* the engine does not draw it (the game does) */
} cw_touch_stick_desc;

typedef struct cw_touch_button_desc {
  cw_touch_corner corner; /* where x, y are measured from (AUTO: bottom right) */
  float x, y;             /* centre, touch units in from the corner; 0, 0 = 110, 110 */
  float radius;           /* touch units; 0 = 48. Touches count up to 1.25 x this (thumbs miss) */
  const char *label;      /* drawn on it (copied, 15 bytes kept); NULL = none */
  cw_color color;         /* its fill; alpha 0 = white */
  bool hidden;            /* the engine does not draw it (the game does) */
} cw_touch_button_desc;

typedef enum {
  CW_TOUCH_OVERLAY_AUTO,   /* drawn on a touch-first device or once a touch lands, until a pad is used */
  CW_TOUCH_OVERLAY_ALWAYS, /* drawn every frame (a desktop test, a demo) */
  CW_TOUCH_OVERLAY_OFF,    /* never drawn: the game draws its own (the controls still work) */
} cw_touch_overlay_mode;

typedef struct cw_jobs_stats {
  uint64_t jobs, chunks;
  uint64_t chunks_by_thread[64];
} cw_jobs_stats;

typedef struct cw_l10n_stats {
  uint32_t catalogs, keys; /* loaded */
  uint32_t lookups;        /* cw_tr* calls (all time) */
  uint32_t missing;        /* distinct missing keys (all time) */
  uint32_t fallback_hits;  /* lookups answered by a catalog after the first in the chain */
  uint32_t locale_hash;    /* FNV-1a of the active locale tag */
  uint32_t font_fallbacks; /* fonts in the active global fallback chain */
} cw_l10n_stats;

typedef struct cw_lightmap_info {
  int meshes, triangles, texels, probes, invalid_probes;
  int width_total;          /* sum of the lightmaps' widths (a size fingerprint) */
  long long rays;
  uint64_t hash;            /* cw_lightmap_hash */
} cw_lightmap_info;

typedef enum {
  CW_EASE_LINEAR, CW_EASE_IN_QUAD, CW_EASE_OUT_QUAD, CW_EASE_IN_OUT_QUAD, CW_EASE_IN_CUBIC, CW_EASE_OUT_CUBIC,
  CW_EASE_IN_OUT_CUBIC, CW_EASE_IN_SINE, CW_EASE_OUT_SINE, CW_EASE_IN_OUT_SINE, CW_EASE_OUT_BACK, CW_EASE_OUT_ELASTIC,
  CW_EASE_OUT_BOUNCE, CW_EASE_COUNT
} cw_ease;

typedef struct cw_cmd_frame {
  uint8_t dir;       /* 1..9, 5 = neutral (relative to facing) */
  uint8_t pad_;
  uint16_t buttons;  /* held mask */
} cw_cmd_frame;

typedef struct cw_cmd_buf {
  cw_cmd_frame f[CW_CMD_HISTORY];
  uint32_t count;     /* frames pushed since clear */
  uint32_t consumed;  /* frames before this index are ignored by matching */
  uint16_t prev;      /* buttons held on the previous frame */
} cw_cmd_buf;

typedef struct cw_motion {
  uint8_t steps[CW_MOTION_MAX_STEPS];
  uint8_t count;
  uint8_t charge; /* the first step is a charge */
  uint8_t exact;  /* bit i: step i must be exactly that direction (written "!6") */
  uint16_t charge_frames; /* frames the charge direction must be held (default 30) */
} cw_motion;

typedef struct cw_nav_filter {
  uint64_t exclude_areas;          /* bit n: never enter area n */
  float area_cost[CW_NAV_AREAS];   /* multiplies distance through the area; must be >= 1 */
} cw_nav_filter;

typedef struct cw_nav_geom {
  CW_ARRAY(float) verts;   /* x, y, z per vertex */
  CW_ARRAY(int32_t) tris;  /* 3 vertex indices per triangle */
  CW_ARRAY(uint8_t) areas; /* one per triangle */
  CW_ARRAY(cw_nav_link) links; /* cw_nav_geom_add_link; a link's id is its index + 1 */
} cw_nav_geom;

typedef enum {
  CW_NAV_PARTITION_WATERSHED, /* best polygons; the default */
  CW_NAV_PARTITION_MONOTONE,  /* fastest; long thin polygons */
  CW_NAV_PARTITION_LAYERS,    /* fast, no holes; good for tiles */
} cw_nav_partition;

typedef struct cw_navmesh_stats {
  int tiles, polys, verts;   /* tiles holding polygons; their polygons and vertices */
  int tiles_x, tiles_z;      /* the tile grid */
  int obstacles;             /* live obstacles (dynamic) */
  int64_t bytes;             /* tile data */
  float build_ms;            /* the last build or update, wall time (never feeds state) */
  int links, links_connected; /* links in the table; those both ends of which reached the navmesh */
} cw_navmesh_stats;

typedef struct cw_nav_hit {
  bool hit;
  float t;
  t3_vec3 point, normal;
} cw_nav_hit;

typedef struct cw_nav_path_req {
  t3_vec3 from, to;
  const cw_nav_filter *filter; /* NULL = default */
} cw_nav_path_req;

typedef enum {
  CW_NAV_PATH_UNKNOWN,  /* no such ticket (never issued, or already taken) */
  CW_NAV_PATH_PENDING,  /* queued */
  CW_NAV_PATH_DONE,     /* a complete path */
  CW_NAV_PATH_PARTIAL,  /* the best path the budget or the navmesh allowed */
  CW_NAV_PATH_FAILED,   /* an end is off the navmesh */
} cw_nav_path_status;

typedef enum {
  CW_CROWD_IDLE,       /* no target */
  CW_CROWD_WAITING,    /* target set, its path not planned yet */
  CW_CROWD_MOVING,
  CW_CROWD_ARRIVED,    /* within arrive_dist of the target */
  CW_CROWD_NO_PATH,    /* target unreachable (the agent stays put) */
  CW_CROWD_VELOCITY,   /* moving by cw_crowd_set_velocity */
  CW_CROWD_ON_LINK,    /* crossing a link (see cw_crowd_agent_state.link) */
} cw_crowd_agent_status;

typedef struct cw_crowd_agent_state {
  t3_vec3 position, velocity;
  t3_vec3 desired_velocity;  /* before avoidance */
  t3_vec3 target, next_corner;
  cw_crowd_agent_status status;
  bool partial;              /* the path ends short of the target */
  int path_polys;            /* corridor length */
  uint32_t path_version;     /* bumped whenever a new path is taken */
  uint32_t link;             /* ON_LINK: the link's id (0 otherwise) */
  float link_progress;       /* ON_LINK: 0 at the start, 1 at the end (stays 0 for manual_links) */
  t3_vec3 link_start, link_end; /* ON_LINK: where the crossing began and where it lands */
} cw_crowd_agent_state;

typedef struct cw_crowd_link_event {
  cw_crowd_agent agent;
  uint32_t link, tag;    /* the link's id and its tag */
  t3_vec3 start, end;    /* the crossing: from the agent's position to the far end */
  float duration;        /* seconds (0 for manual_links) */
  bool finished;         /* false: began this step; true: landed this step */
} cw_crowd_link_event;

typedef struct cw_crowd_stats {
  int agents, moving, waiting;
  int paths_planned;      /* during the last step */
  int neighbor_pairs;     /* neighbours found in the last step */
  float step_ms;          /* the last step, wall time (never feeds state) */
  float phase_ms[4];      /* paths, neighbours, steering, movement */
} cw_crowd_stats;

functions.doc:
UDP (native): bound to `port` on every interface (0 = any free port);
open("udp:host:port" or "host:port"), IPv4. A datagram from an unknown
address opens a new link. NULL in carts (no sockets) and on bind failure.

types.decl:
typedef struct cw_net_event {
  cw_net_event_type type;
  int link;
  const uint8_t *data;
  int len;
} cw_net_event;

typedef struct cw_net_sim_desc {
  double latency; /* seconds, one way */
  double jitter;  /* seconds, uniform 0..jitter added per datagram */
  float loss;     /* 0..1 */
  float dup;      /* 0..1 */
  uint64_t seed;
} cw_net_sim_desc;

typedef struct cw_net_session_desc {
  cw_net_transport *transport; /* owned by the session from now on */
  int local_player;            /* this peer's slot; -1 = take the slot the transport assigns (relay) */
  uint32_t protocol;           /* the game's protocol id + version */
  double timeout;              /* seconds without a packet before a peer drops (5) */
} cw_net_session_desc;

typedef struct cw_net_peer_stats {
  double rtt;                    /* smoothed round trip, seconds */
  uint32_t packets_sent, packets_received, packets_lost; /* lost: never acked */
  uint32_t resends;              /* reliable messages sent again */
  uint32_t bytes_sent, bytes_received;
} cw_net_peer_stats;

typedef struct cw_rollback_desc {
  cw_net_session *session; /* NULL: every player is local (sample_input is asked for each) */
  cw_tree *tree;
  int players;          /* 1..CW_NET_MAX_PEERS, slots 0..players-1 */
  int input_size;       /* bytes per player per tick, 1..CW_ROLLBACK_MAX_INPUT */
  int input_delay;      /* ticks; 0 = none (every prediction can miss); 2 hides 2 ticks of latency */
  int max_prediction;   /* ticks (8) */
  int hash_interval;    /* ticks between desync checks (10) */
  double dt;            /* fixed step seconds (1/60) */
  /* the local player's input for the tick about to be scheduled */
  void (*sample_input)(cw_rollback *rb, int player, void *out, void *user);
  void *user;
  bool no_rollback;     /* test control: wrong predictions are never corrected */
} cw_rollback_desc;

typedef enum {
  CW_NOISE_OPENSIMPLEX2,
  CW_NOISE_OPENSIMPLEX2S,
  CW_NOISE_CELLULAR,
  CW_NOISE_PERLIN,
  CW_NOISE_VALUE_CUBIC,
  CW_NOISE_VALUE,
  CW_NOISE_TYPE_COUNT
} cw_noise_type;

typedef enum {
  CW_NOISE_FRACTAL_NONE,
  CW_NOISE_FRACTAL_FBM,
  CW_NOISE_FRACTAL_RIDGED,
  CW_NOISE_FRACTAL_PINGPONG,
  CW_NOISE_FRACTAL_WARP_PROGRESSIVE, /* domain warp only: each octave warps the result of the last */
  CW_NOISE_FRACTAL_WARP_INDEPENDENT, /* domain warp only: every octave warps the input */
  CW_NOISE_FRACTAL_COUNT
} cw_noise_fractal;

typedef enum {
  CW_NOISE_DIST_EUCLIDEAN,
  CW_NOISE_DIST_EUCLIDEAN_SQ,
  CW_NOISE_DIST_MANHATTAN,
