  CW_NOISE_CELL_DISTANCE2_SUB,
  CW_NOISE_CELL_DISTANCE2_MUL,
  CW_NOISE_CELL_DISTANCE2_DIV,
  CW_NOISE_CELL_RETURN_COUNT
} cw_noise_cellular_return;

typedef enum {
  CW_NOISE_WARP_NONE,
  CW_NOISE_WARP_OPENSIMPLEX2,
  CW_NOISE_WARP_OPENSIMPLEX2_REDUCED,
  CW_NOISE_WARP_BASIC_GRID,
  CW_NOISE_WARP_COUNT
} cw_noise_warp;

typedef struct cw_particles_stats {
  int systems;        /* GPUParticles3D nodes in the tree */
  int alive;          /* sum of their `alive` */
  int capacity;       /* sum of their `amount` */
  int sim_steps;      /* transform feedback steps run last frame */
  int draw_calls;     /* particle + trail draws last frame */
  int sort_passes;    /* bitonic passes last frame */
} cw_particles_stats;

typedef struct cw_phys_material {
  float friction, restitution, rolling_resistance;
  float tangent_speed;   /* 2D */
  float tangent_velocity[3]; /* 3D, shape-local */
  uint64_t user_material;
} cw_phys_material;

typedef enum {
  CW_PHYS_CONTACT_BEGIN, /* shape_a, shape_b started touching */
  CW_PHYS_CONTACT_END,   /* stopped touching */
  CW_PHYS_HIT,           /* point, normal (a to b), speed, materials */
  CW_PHYS_SENSOR_ENTER,  /* shape_a = sensor, shape_b = visitor */
  CW_PHYS_SENSOR_EXIT,
  CW_PHYS_JOINT_BREAK,   /* joint (now destroyed), body_a/b, user */
  CW_PHYS_EVENT_TYPE_COUNT
} cw_phys_event_type;

typedef struct cw_phys_filter {
  uint32_t layers;
  bool sensors;
  uint64_t ignore_body;
  bool (*fn)(uint64_t shape_id, void *ctx);
  void *ctx;
} cw_phys_filter;

typedef struct cw_phys_stats {
  int32_t bodies, awake_bodies, shapes, contacts, joints;
  int32_t events;      /* in the last step's list */
  int32_t steps;       /* steps since creation */
  uint32_t hash;       /* running hash of every step's moved transforms and events */
  float step_ms;       /* the library's own step time (profiling only: host-dependent) */
} cw_phys_stats;

typedef struct cw_phys_lines {
  CW_ARRAY(float) pos;
  CW_ARRAY(uint32_t) color;
} cw_phys_lines;

typedef enum {
  CW_JOINT_DISTANCE, CW_JOINT_FILTER, CW_JOINT_MOTOR, CW_JOINT_PRISMATIC, CW_JOINT_REVOLUTE, CW_JOINT_WELD,
  CW_JOINT_WHEEL, CW_JOINT_MOUSE, CW_JOINT_SPHERICAL, CW_JOINT_PARALLEL, CW_JOINT_MOVER, CW_JOINT_POGO,
  CW_JOINT_TYPE_COUNT
} cw_joint_type;

typedef struct cw_rot2 {
  float c, s;
} cw_rot2;

typedef struct cw_xform2 {
  cw_vec2 p;
  cw_rot2 q;
} cw_xform2;

typedef struct cw_pos2 {
  double x, y;
} cw_pos2;

typedef struct cw_wxform2 {
  cw_pos2 p;
  cw_rot2 q;
} cw_wxform2;

typedef struct cw_phys_capacity2d {
  int static_shapes, dynamic_shapes, static_bodies, dynamic_bodies, contacts, arena_bytes;
} cw_phys_capacity2d;

typedef struct cw_world2d_def {
  cw_vec2 gravity;             /* (0, -10) */
  int substeps;                /* 4 */
  int workers;                 /* job-pool threads the step may use: 0 = all */
  float hit_speed;             /* 1 m/s */
  float restitution_threshold; /* 1 m/s */
  int restitution_iterations;  /* 0 = Box2D's default */
  bool restitution_propagation; /* false = Box2D's default */
  float max_linear_speed;      /* m/s, 0 = Box2D's default */
  cw_phys_capacity2d capacity; /* expected counts, to size the world once (all zero: grow as needed) */
  bool sleep, continuous;      /* true, true */
  const char *layers[CW_PHYS_LAYERS];
} cw_world2d_def;

typedef struct cw_phys_event2d {
  cw_phys_event_type type;
  cw_shape2d shape_a, shape_b;
  cw_body2d body_a, body_b;
  cw_joint2d joint;
  cw_pos2 point;
  cw_vec2 normal;
  float speed;
  uint64_t material_a, material_b;
  void *user;
} cw_phys_event2d;

typedef struct cw_aabb2 {
  cw_vec2 lo, hi; /* floats: exact within a few km of the origin */
} cw_aabb2;

typedef struct cw_world2d_profile {
  float step, pairs, collide, solve, solver_setup, constraints, prepare_constraints, integrate_velocities, warm_start,
      solve_impulses, integrate_positions, relax_impulses, restitution, store_impulses, split_islands, transforms,
      sensor_hits, joint_events, hit_events, refit, bullets, sleep_islands, sensors;
} cw_world2d_profile;

typedef struct cw_world2d_counters {
  size_t byte_count;
  int bodies, shapes, contacts, awake_contacts, recycled_contacts, joints, islands, stack_used, static_tree_height,
      tree_height, tasks;
  int color_counts[24]; /* constraints per solver graph colour */
} cw_world2d_counters;

typedef struct cw_replay2d_info {
  int frames;       /* recorded steps */
  float dt;         /* the recorded step */
  int substeps;
  cw_aabb2 bounds;  /* the world bounds over the recording */
} cw_replay2d_info;

typedef enum cw_replay2d_query_type {
  CW_REPLAY2D_OVERLAP_AABB, CW_REPLAY2D_OVERLAP_SHAPE, CW_REPLAY2D_CAST_RAY, CW_REPLAY2D_CAST_SHAPE,
  CW_REPLAY2D_COLLIDE_MOVER, CW_REPLAY2D_CAST_RAY_CLOSEST, CW_REPLAY2D_CAST_MOVER
} cw_replay2d_query_type;

typedef struct cw_replay2d_query {
  cw_replay2d_query_type type;
  cw_pos2 origin;       /* where the query started (the box and shape points are relative to it) */
  cw_aabb2 aabb;        /* the box of an AABB overlap, relative to origin */
  cw_vec2 translation;  /* rays and casts */
  int hit_count;
} cw_replay2d_query;

typedef struct cw_replay2d_hit {
  b2ShapeId shape;
  cw_pos2 point;
  cw_vec2 normal;
  float fraction;
} cw_replay2d_hit;

typedef struct cw_body2d_def {
  cw_body_type type;           /* CW_BODY_DYNAMIC */
  cw_pos2 position;
  cw_rot2 rotation;            /* (1, 0) */
  cw_vec2 linear_velocity;
  float angular_velocity;
  float linear_damping, angular_damping, gravity_scale; /* 0, 0, 1 */
  bool lock_rotation, bullet;
  bool awake, sleep, interpolate; /* true, true, true */
  float safety_factor;         /* continuous collision, 0.01..0.5: Box2D's default (smaller is safer, can hitch) */
  bool allow_fast_rotation;    /* false */
  bool contact_recycling;      /* true: reuse contact points while the shapes barely move */
  bool enabled;                /* true; false = created disabled (no collision, no step) */
  const char *name;
  void *user;
} cw_body2d_def;

typedef struct cw_shape2d_def {
  cw_phys_material material;
  float density;               /* kg/m^2: 1 */
  int layer;
  uint32_t mask;
  int group;
  bool sensor, contact_events, sensor_events, hit_events; /* false, true, true, false */
  uint32_t debug_color;        /* 0xRRGGBB for this shape's wireframe; 0 = by body state */
  void *user;
} cw_shape2d_def;

typedef struct cw_joint2d_def {
  cw_joint_type type;
  cw_body2d a, b;
  /* Local frames. PRISMATIC / WHEEL travel along x of frame a; REVOLUTE
   * turns about the frames' origin. */
  cw_xform2 frame_a, frame_b;
  bool collide_connected;
  float break_force, break_torque;
  bool spring;
  float hertz, damping_ratio;
  bool limit;
  float lower, upper;
  bool motor;
  float motor_speed, max_motor;
  float length;
  float max_force;
  cw_pos2 target;
  /* MOVER: the commanded velocity (m/s) and the most force that may chase it, x and y separately (N). */
  cw_vec2 linear_velocity, max_velocity_force;
  /* POGO: a spring between frame_a's point (on body a) and frame_b's point (on body b), measured along +y of
   * frame_b (hertz, damping_ratio and length are its spring and rest length); it pushes on the bodies along
   * `normal` (the world normal of the ground it stands on), at most max_tension_force pulling and
   * max_compression_force pushing; pogo_impulse / pogo_velocity carry its state across a recreation (the pogo is
   * usually made again every frame). */
  cw_vec2 normal;
  float max_tension_force, max_compression_force, pogo_impulse, pogo_velocity;
  void *user;
} cw_joint2d_def;

typedef struct cw_ray_hit2d {
  cw_shape2d shape;
  cw_body2d body;
  cw_pos2 point;
  cw_vec2 normal;
  float fraction;
  uint64_t material;
  int triangle;                /* always -1 in 2D (kept for parity) */
} cw_ray_hit2d;

typedef struct cw_ray2d {
  cw_pos2 origin;
  cw_vec2 translation;
} cw_ray2d;

typedef struct cw_qshape2d {
  cw_vec2 points[CW_QSHAPE2D_POINTS]; /* relative to origin */
  int count;
  float radius;
  cw_pos2 origin; /* zero from the constructors; cw_qshape2d_at moves the shape (the points keep their precision) */
} cw_qshape2d;

typedef struct cw_mover2d_def {
  float radius, height;        /* 0.3, 1.8 */
  float max_floor_angle;       /* 45 degrees */
  float step_height, snap_length, skin; /* 0.3, 0.25, 0.02 (skin <= 0 becomes 0.02) */
  int max_iterations;          /* 5 */
  uint32_t mask;
  float push_mass;
  bool ride_platforms;
  /* Layers (bits, as mask) whose shapes are one-way platforms: solid only from above. The mover lands on and
   * walks across their top faces, rises through them from below and passes them sideways; it stays inside one
   * (feet below the top) until clear. 0 = none. Put the shapes on a layer in this mask. */
  uint32_t one_way_mask;
  /* Corner correction, metres (0 = off, the default): when a rising body would hit the edge of a ceiling block
   * with that much of its width, it is nudged sideways around the corner and keeps rising (the smallest nudge that
   * clears wins; deeper clips still bump). Ledge forgiveness needs no setting: the capsule's round feet roll up a
   * lip of up to about 0.85 * radius, so a fall that just misses a ledge top lands on it. */
  float corner_correction;
} cw_mover2d_def;

typedef struct cw_mover2d {
  cw_world2d world;
  cw_mover2d_def def;
  cw_pos2 position, prev_position;
  cw_vec2 velocity;
  bool on_floor, on_wall, on_ceiling, stepped, snapped;
  cw_vec2 floor_normal, wall_normal;
  cw_body2d floor_body;
  cw_vec2 platform_velocity;
  float floor_cos;
  /* Set by the game before a move to fall through the one-way platform it stands on (a down + jump press). */
  bool drop_through;
  /* The floor is a one-way platform (so down + jump may drop through it). */
  bool on_one_way;
} cw_mover2d;

typedef struct cw_xform3 {
  t3_vec3 p;
  t3_quat q;
} cw_xform3;

typedef struct cw_world3d_def {
  t3_vec3 gravity;             /* (0, -10, 0) */
  int substeps;                /* solver sub-steps per step: 4 */
  int workers;                 /* job-pool threads the step may use: 0 = all */
  float hit_speed;             /* hit events above this approach speed: 1 m/s */
  float restitution_threshold; /* bounce above this speed: 1 m/s */
  bool sleep, continuous;      /* true, true */
  const char *layers[CW_PHYS_LAYERS]; /* layer names (copied); NULL = unnamed */
} cw_world3d_def;

typedef struct cw_phys_event3d {
  cw_phys_event_type type;
  cw_shape3d shape_a, shape_b; /* sensor events: a = sensor, b = visitor */
  cw_body3d body_a, body_b;    /* null when the shape is gone */
  cw_joint3d joint;            /* joint break */
  t3_vec3 point, normal;       /* hit: world point, normal from a to b */
  float speed;                 /* hit: approach speed */
  uint64_t material_a, material_b; /* hit: user materials */
  void *user;                  /* joint break: the joint's user pointer */
} cw_phys_event3d;

typedef struct cw_body3d_def {
  cw_body_type type;            /* CW_BODY_DYNAMIC */
  t3_vec3 position;
  t3_quat rotation;             /* identity */
  t3_vec3 linear_velocity, angular_velocity;
  float linear_damping, angular_damping; /* 0, 0 */
  float gravity_scale;          /* 1 */
  bool lock_rotation;           /* no rotation at all (motion locks) */
  bool bullet;                  /* continuous vs other dynamic bodies */
  bool awake, sleep;            /* true, true */
  bool interpolate;             /* keep a prev/current pair for sync: true */
  const char *name;             /* debugging, copied */
  void *user;
} cw_body3d_def;

typedef struct cw_contact3d {
  cw_shape3d shape;            /* this body's shape */
  cw_shape3d other_shape;
  cw_body3d other;
  t3_vec3 point;               /* world: the points weighted by impulse (their middle when none pushed) */
  t3_vec3 normal;              /* from this body toward the other */
  float impulse;               /* N*s: Box3D's total normal impulse over the last step's sub-steps; it
                                  counts the solve and the relax pass, so it runs about twice the
                                  momentum the contact moved: a measure of how hard, not a momentum */
  float approach;              /* m/s: the fastest approach before the solve (> 0 closing) */
  t3_vec3 slide;               /* m/s: the other's velocity against this one at the point, across the normal */
} cw_contact3d;

typedef struct cw_shape3d_def {
  cw_phys_material material;
  float density;               /* kg/m^3: 1 */
  int layer;                   /* 0..31: 0 */
  uint32_t mask;               /* layers it collides with (queries never see sensors): all */
  int group;                   /* 0; <0 never collide within, >0 always */
  bool sensor;                 /* overlap events, no response */
  bool contact_events;         /* begin/end: true */
  bool sensor_events;          /* detected by / detecting sensors: true */
  bool hit_events;             /* false */
  void *user;
} cw_shape3d_def;

typedef struct cw_joint3d_def {
  cw_joint_type type;
  cw_body3d a, b;              /* MOUSE: b is the dragged body, a unused */
  /* Joint frames in each body's local space. Axes: REVOLUTE turns about z;
   * PRISMATIC slides along x of frame a; WHEEL spins about z of frame b and
   * travels along x of frame a; SPHERICAL cone about z of frame a, twist
   * about z of frame b. cw_joint3d_def_anchor fills both from world data. */
  cw_xform3 frame_a, frame_b;
  bool collide_connected;
  /* Break when the joint force (N) or torque (N*m) exceeds this; 0 = never.
   * A broken joint is destroyed after the step and reported as
   * CW_PHYS_JOINT_BREAK. */
  float break_force, break_torque;
  bool spring;                 /* revolute, prismatic, distance, spherical, wheel (suspension) */
  float hertz, damping_ratio;  /* spring (and weld / motor / mouse stiffness) */
  bool limit;                  /* revolute/spherical twist: angles; prismatic/wheel: translation */
  float lower, upper;          /* distance: min/max length */
  bool motor;
  float motor_speed;           /* rad/s or m/s */
  float max_motor;             /* torque or force */
  float length;                /* distance: rest length; 0 = current anchor distance */
  float cone_angle;            /* spherical: cone limit when limit is set */
  float max_force;             /* mouse / motor: max spring force, 0 = 1000 x weight */
  t3_vec3 target;              /* mouse: world target (and grab point at creation) */
  void *user;
} cw_joint3d_def;

