                     * instead of bars (a 320x180 canvas is 240x180 on 4:3, 432x180 on 21:9;
                     * cw_r2d_canvas_size says); Camera2D limits still hold */
} cw_scale_mode;

typedef struct cw_r2d_pass_desc {
  cw_texture target;    /* null = the window (framebuffer 0) */
  bool clear;
  cw_color clear_color;
  /* window passes: draw at virtual_width x virtual_height (nearest-filtered
   * canvas) and scale it to the window by `scale`; 0 = no virtual canvas */
  int virtual_width, virtual_height;
  cw_scale_mode scale;
  cw_color letterbox;   /* bars around a scaled canvas (alpha forced to 1) */
  float time;           /* seconds: animated tiles (pass a tick-derived time for replays) */
  cw_color ambient;     /* lit layers: light where no light reaches; all 0 = black */
} cw_r2d_pass_desc;

typedef struct cw_r2d_layer_desc {
  bool has_camera;      /* false = screen space (identity) */
  cw_camera2d camera;
  cw_vec2 parallax;     /* camera position factor; (0,0) = (1,1) */
  cw_rect viewport;     /* canvas pixels; w == 0 = the whole canvas. Draws are clipped to it. */
  bool y_sort;          /* within equal z: sort by y (sprite pivot / shape anchor), lower first */
  bool pixel_snap;      /* round transformed vertices to whole canvas pixels */
  bool lit;             /* drawn through the 2D light pass (see lights) */
} cw_r2d_layer_desc;

typedef enum {
  CW_BLEND_ALPHA,    /* premultiplied over */
  CW_BLEND_ADD,      /* additive; batches with ALPHA (no state change) */
  CW_BLEND_MULTIPLY, /* dst * src (own batch) */
  CW_BLEND_OPAQUE,   /* replace (own batch) */
} cw_blend;

typedef struct cw_sprite {
  cw_texture texture; /* null = solid colour rectangle */
  cw_rect src;        /* texture pixels (atlas region); w == 0 = whole texture */
  cw_vec2 pos;        /* where the pivot lands (layer space) */
  cw_vec2 size;       /* drawn size; 0 = src size */
  cw_vec2 scale;      /* (0,0) = (1,1) */
  cw_vec2 pivot;      /* 0..1 inside the sprite, (0,0) = top-left, (0.5,0.5) = centre */
  float rotation;     /* radians clockwise, about the pivot */
  cw_color color;     /* modulate; {0,0,0,0} (zero-init) = white */
  bool flip_x, flip_y;
  int z;              /* added to cw_r2d_set_z */
} cw_sprite;

typedef struct cw_nine_slice {
  cw_texture texture;
  cw_rect src;                    /* w == 0 = whole texture */
  float left, top, right, bottom; /* margins, texture pixels */
  cw_rect dst;
  cw_color color;                 /* {0,0,0,0} = white */
  float margin_scale;
  bool hollow;                    /* skip the centre */
} cw_nine_slice;

typedef struct cw_font_desc {
  cw_font_mode mode;
  float bake_size;     /* SDF: em size glyphs are baked at (0 = 48); BITMAP: the pixel size (0 = 16) */
  int sdf_padding;     /* SDF: distance range in baked pixels (0 = 6) */
  bool threshold;      /* BITMAP: 1-bit glyphs (crisp pixel fonts) */
} cw_font_desc;

typedef struct cw_text_metrics {
  float width, height;  /* box of the laid-out text (height = lines * line height) */
  int lines;
  float ascent, descent, line_height; /* at this size; descent is negative */
} cw_text_metrics;

typedef struct cw_tilemap_desc {
  int width, height;      /* tiles */
  int layers;             /* 1..16 */
  cw_texture tileset;     /* an image texture (not a render target) */
  int tile_w, tile_h;     /* tileset cell size, texture pixels */
  int margin, spacing;    /* tileset border / gap between cells, pixels */
  int columns;            /* tiles per tileset row; 0 = from the texture width */
  float cell_w, cell_h;   /* world size of one tile; 0 = tile_w/tile_h */
} cw_tilemap_desc;

typedef struct cw_light2d {
  cw_vec2 pos;          /* layer space */
  float radius;         /* layer units; light is 0 at the radius */
  cw_color color;       /* {0,0,0,0} = white */
  float energy;         /* 0 = 1 */
  float falloff;        /* exponent of (1 - d/radius); 0 = 2 */
  float height;         /* above the plane, layer units, for normal maps; 0 = radius/4 */
  bool shadows;         /* cast shadows from occluders */
} cw_light2d;

typedef struct cw_r2d_stats {
  uint32_t passes;
  uint32_t draw_calls;     /* every glDraw* the renderer issued */
  uint32_t batches;        /* draws of the sorted stream (sprites/shapes/text) */
  uint32_t vertices;       /* submitted to the stream */
  uint32_t indices;
  uint32_t commands;       /* sprites + shapes + text runs + tilemap layers */
  uint32_t sorted;         /* passes that needed the sort */
  uint32_t tile_chunks;    /* chunks drawn */
  uint32_t chunk_rebuilds;
  uint32_t lights;
  uint32_t atlas_pages;    /* pages across atlas arrays (all time) */
  uint32_t texture_uploads;
  /* complex-script runs laid out this frame, by every measure and draw:
   * shaped now or reused from the shape cache (cached text still counts) */
  uint32_t shaped_runs;
  uint32_t glyphs_missing; /* distinct codepoints no font in the chain had (all time) */
  uint32_t shape_cache_hits; /* complex layouts this frame served by the shape cache (no shaping) */
} cw_r2d_stats;

typedef struct cw_render3d_stats {
  int draw_calls, triangles, programs;
  float cpu_ms;
  int skipped; /* draws three.c could not make since the tree began (each reason logged once): should be 0 */
} cw_render3d_stats;

functions.doc:
A resource built from memory instead of a file (procedural content, tests,
the editor). Synchronous; path names it in the cache ("gen://noise" etc.;
loading that path again returns it).

types.decl:
typedef enum {
  CW_RES_STATE_NONE,    /* null or stale handle */
  CW_RES_STATE_LOADING, /* queued, decoding, or waiting for its upload turn */
  CW_RES_STATE_READY,
  CW_RES_STATE_FAILED,  /* the log says why; the handle stays valid */
} cw_res_state;

typedef struct cw_res_load_opts {
  int lane;              /* lower lanes finish first (0 = default; e.g. 0 for what the sim needs, 1 for visuals) */
  int priority;          /* within a lane, higher finishes first (0 = default) */
  cw_res_done_fn done;   /* may be NULL */
  void *user;
} cw_res_load_opts;

typedef struct cw_res_group_progress {
  int total, ready, failed, loading;
  float fraction;     /* (ready + failed) / total: a loading bar */
  int64_t bytes;      /* payload bytes ready */
  int64_t file_bytes; /* packed bytes read for them */
} cw_res_group_progress;

typedef struct cw_res_stats {
  int live;          /* slots in use (any state, pending free included) */
  int ready, loading, failed, pending_free;
  int64_t bytes;     /* payload bytes of READY resources (CPU + GPU estimate) */
  uint64_t loads;    /* load calls, cache hits included */
  uint64_t cache_hits;
  uint64_t decoded;  /* files decoded (sync + async) */
  uint64_t freed;
  uint64_t uploaded_bytes_last_frame;
  int finished_last_frame;
  int by_type[32];   /* READY resources per type id (first 32 types) */
  /* load cost so far (wall clock: for reports, never for game logic) */
  double read_ms;    /* reading files (main thread; a lazily loaded web cart waits on the network here) */
  double decode_ms;  /* decoding (job pool, summed over workers) */
  double finish_ms;  /* finishing: three.c objects, GPU uploads (main thread) */
  int64_t file_bytes; /* packed bytes read */
  int64_t cpu_bytes; /* CW_MEM_RESOURCE now: bookkeeping, decoded data, kept files */
  /* the background pipeline and the residency cache */
  int waiting;       /* async loads not started yet (a cart: not read yet) */
  int in_flight;     /* reads + decodes running on the job pool */
  int cached;        /* READY with no references, kept by the residency budget */
  int64_t cached_bytes; /* their size as the budget counts it */
  uint64_t evicted;  /* cached resources freed to fit the budget */
  uint64_t cancelled; /* async loads released before they finished */
} cw_res_stats;

typedef struct cw_res_info {
  cw_res_type type;
  cw_res_state state;
  const char *path;
  uint64_t uid;
  uint32_t version;
  int refs;
  size_t file_bytes;           /* packed size read for the last (re)load */
  int64_t bytes;               /* payload (CPU + GPU estimate) */
  double read_ms, decode_ms, finish_ms;
  double total_ms;             /* request to READY */
  int frames_to_ready;         /* frame boundaries between request and READY */
} cw_res_info;

typedef struct cw_res_decode_args {
  const char *path;          /* canonical */
  const uint8_t *bytes;      /* the file (NUL-terminated, not counted) */
  size_t len;
  int extra_count;           /* files added with cw_res_prepare_read */
  const char *const *extra_paths;
  const uint8_t *const *extra_bytes;
  const size_t *extra_lens;
  void *type_user;
  /* set *take_bytes = true to keep `bytes` as part of the result (free it
   * later with cw_free) instead of copying it */
  bool *take_bytes;
} cw_res_decode_args;

typedef struct cw_res_type_desc {
  const char *name;        /* "texture"; unique */
  const char *extensions;  /* ".png .jpg" (lower case) for CW_RES_TYPE_AUTO */
  /* main thread, optional: called with the file read, before decode; asks
   * for dependencies / extra files. false = FAILED (log why). */
  bool (*prepare)(cw_res_prepare *p, void *type_user);
  /* WORKER-SAFE: bytes -> decoded intermediate. No GL, no three.c object
   * creation (three.c ids must be handed out in order on one thread), no
   * cw_res_* calls. NULL = FAILED (log why). *cost = payload bytes the
   * finish step will upload (for the budget). */
  void *(*decode)(const cw_res_decode_args *a, size_t *cost);
  /* main thread: decoded -> payload (create three.c objects, upload). Owns
   * decoded either way. deps[i] are the prepare dependencies, READY or
   * FAILED. NULL = FAILED. */
  void *(*finish)(void *decoded, cw_res self, const cw_res *deps, int dep_count, void *type_user);
  /* main thread: free a payload. */
  void (*unload)(void *payload, void *type_user);
  /* main thread, optional: drop a decoded intermediate never finished
   * (the load was released before it finished). */
  void (*discard)(void *decoded, void *type_user);
  /* main thread, optional: hot reload. Move fresh into payload IN PLACE so
   * pointers others hold stay valid, then free what is left of fresh.
   * Without it, the handle's payload pointer is swapped and fresh's old
   * payload freed (holders re-read cw_res_get; cw_res_version tells). */
  void (*reload)(void *payload, void *fresh, void *type_user);
  /* optional: payload bytes for stats */
  size_t (*size)(const void *payload, void *type_user);
  void *type_user;
  /* main thread, optional: called at every load request of this type,
   * before the file is read (on a worker, for an async load without a
   * prepare step): set up what decode needs from the main thread (the
   * texture type picks its KTX2 target here). A type with prepare has its
   * fi ...

typedef struct cw_blob {
  const uint8_t *data;
  size_t len;
} cw_blob;

typedef enum {
  CW_AUDIO_UNKNOWN, CW_AUDIO_WAV, CW_AUDIO_OGG_VORBIS, CW_AUDIO_MP3, CW_AUDIO_FLAC, CW_AUDIO_OGG_OPUS, CW_AUDIO_MODULE
} cw_audio_container;

typedef struct cw_audio_clip {
  const uint8_t *data;
  size_t len;
  cw_audio_container container;
  uint32_t sample_rate, channels;
  uint64_t frames;   /* PCM frames, 0 when unknown */
  double seconds;
} cw_audio_clip;

typedef struct cw_texture_info {
  int width, height, levels;
  uint32_t gl_internal_format; /* GL_RGBA8, GL_COMPRESSED_RGBA_BPTC_UNORM_EXT, ... */
  const char *format;          /* "rgba8", "bc7", "astc4x4", "etc2", "bc3" */
  bool from_ktx2;
  size_t gpu_bytes;            /* all levels */
} cw_texture_info;

typedef struct cw_mesh {
  struct t3_geometry *lod[CW_MESH_MAX_LODS];
  float lod_error[CW_MESH_MAX_LODS]; /* simplifier error relative to the mesh extent (0 for lod 0) */
  int lod_triangles[CW_MESH_MAX_LODS];
  int lod_count;
  struct t3_material *material;
  float extent;      /* the largest side of lod[0]'s bounding box: lod_error x extent is the error in mesh units */
} cw_mesh;

typedef struct cw_gltf {
  struct t3_gltf *gltf;      /* gltf->scene is the template; do not add it to a scene */
  int mesh_count;            /* sub-resources "#mesh/m/p" */
  int material_count, texture_count;
  uint64_t mesh_hash;        /* FNV-1a 64 over every geometry's attributes + indices, scene order */
  int vertices, triangles;   /* LOD 0, all primitives once */
  int lod_levels;            /* max LOD count over its meshes */
  int64_t bytes;             /* geometry + texture bytes */
} cw_gltf;

macros.doc:
Meshes: one glTF primitive, its LOD chain (cwpack's simplifier output;
lod[0] is the full mesh) and its material. Every LOD geometry shares the
full mesh's vertex attributes; only the index buffer differs.

types.decl:
typedef struct cw_rim_light_desc {
  t3_color color;   /* the glow's colour (linear; 1, 0.3, 0.2) */
  float strength;   /* its brightness, emissive units (2) */
  float power;      /* how tight to the edge, 1 = broad, 8 = a thin line (3) */
  float near, far;  /* metres from the camera where it fades in (6 to 20) */
  float close;      /* the share of the strength it keeps below `near` (0.15) */
} cw_rim_light_desc;

typedef enum {
  CW_T_NONE, CW_T_BOOL, CW_T_INT, CW_T_FLOAT, CW_T_VEC2, CW_T_VEC3, CW_T_VEC4, CW_T_QUAT, CW_T_COLOR,
  CW_T_STRING, CW_T_NODE, CW_T_RES, CW_T_ENUM, CW_T_COUNT
} cw_type;

typedef struct cw_value {
  cw_type type;
  union {
    bool b;
    int64_t i;
    double f;
    float v[4]; /* vec2/3/4, quat (xyzw), color (rgba, linear) */
    const char *s; /* interned */
    cw_node node;
    uint64_t res;  /* resource uid (resource.h) */
  };
} cw_value;

typedef enum {
  CW_PROP_STORED = 1 << 0,   /* saved in scenes */
  CW_PROP_EDITOR = 1 << 1,   /* shown in the inspector */
  CW_PROP_READONLY = 1 << 2, /* set refused (computed values) */
  CW_PROP_ANIMATABLE = 1 << 3,
  CW_PROP_DEFAULT = CW_PROP_STORED | CW_PROP_EDITOR | CW_PROP_ANIMATABLE,
} cw_prop_flags;

typedef struct cw_prop {
  const char *name;
  cw_type type;
  uint32_t flags;
  /* field access: offset into the type's data (-1 when get/set are used) */
  int offset;
  int size;
  void (*get)(cw_node n, void *data, cw_value *out);
  void (*set)(cw_node n, void *data, const cw_value *in);
  /* hints for editors / validation */
  double min, max;
  const char *const *enum_names; /* CW_T_ENUM: NULL-terminated */
  const char *doc;
} cw_prop;

typedef enum {
  CW_PAUSE_INHERIT, CW_PAUSE_PAUSABLE, CW_PAUSE_WHEN_PAUSED, CW_PAUSE_ALWAYS, CW_PAUSE_DISABLED
} cw_pause_mode;

typedef struct cw_connection_info {
  uint64_t id;
  cw_node emitter, target;
  const char *signal, *method;
  uint32_t flags; /* cw_connect_flags */
} cw_connection_info;

typedef struct cw_method {
  const char *type, *name; /* interned */
  const char *args;
  cw_method_fn fn;
  void *user;
  const char *doc;
} cw_method;

typedef struct cw_node3d {
  t3_vec3 position;
  t3_vec3 rotation; /* euler XYZ, radians (editor convenience; kept in sync with quaternion) */
  t3_quat quaternion;
  t3_vec3 scale;
  bool visible;
  int32_t layers;      /* render layers, bit n = layer n (default 1); -1 = every layer (lights). See Camera3D layers. */
  /* engine-owned */
  t3_object *object;   /* the three.c object this node drives (a t3_group by default) */
  bool interpolate;    /* render between the last two fixed ticks (physics bodies set it) */
  t3_vec3 prev_position;
  t3_quat prev_quaternion;
  t3_mat4 world;       /* last computed world matrix */
} cw_node3d;

typedef struct cw_node2d {
  cw_vec2 position;
  float rotation; /* radians */
  cw_vec2 scale;
  float skew;
  int z_index;
  bool z_relative;
  bool visible;
  cw_vec2 prev_position;
  float prev_rotation;
  bool interpolate;
  float world[6]; /* affine: a b c d tx ty */
  float modulate[4];      /* rgba multiplied into this node and its children (inherited) */
  float self_modulate[4]; /* rgba multiplied into this node only */
} cw_node2d;

typedef struct cw_canvas_item {
  cw_xform2d xform;
  cw_color modulate;
  int layer, z;
  float alpha;
} cw_canvas_item;

typedef struct cw_canvas_view {
  cw_texture target;     /* a render target (cw_target_create); its size is the canvas */
  bool use_camera;       /* use camera below instead of the tree's current Camera2D */
  cw_camera2d camera;
  bool clear;            /* clear to clear_color first */
  cw_color clear_color;
  bool skip_overlays;    /* do not run the overlay passes (UI) */
} cw_canvas_view;

typedef struct cw_canvas_stats {
  int32_t items, layers, lights, occluders;
} cw_canvas_stats;

typedef struct cw_scene_section {
  const char *name;               /* "animation" */
  const char *const *subsections; /* NULL-terminated sub-header names it owns while open */
  /* a new section's header line; returns its parsed state, NULL on error (logged) */
  void *(*begin)(const char *header, const char *path, int lineno);
  /* a body line or an owned sub-header (leading whitespace trimmed); false on error */
  bool (*line)(void *state, const char *line, const char *path, int lineno);
  /* the scene was instanced: root is the new subtree (not in a tree yet) */
  void (*instance)(void *state, cw_node root, const char *path);
  void (*free)(void *state);
  /* append this extension's sections for the subtree under root */
  void (*save)(cw_node root, void (*put)(void *ctx, const char *text), void *ctx);
} cw_scene_section;

typedef enum {
  CW_SHELL_LOADING,  /* the game is loading (cw_shell_loading / cw_shell_loaded) */
  CW_SHELL_TITLE,
  CW_SHELL_JOIN,     /* players join (max_players > 1) */
  CW_SHELL_PLAY,     /* gameplay: cw_shell_update returns true */
  CW_SHELL_PAUSE,
  CW_SHELL_SETTINGS, /* from the title or the pause menu */
} cw_shell_screen;

typedef struct cw_shell_desc {
  const char *title;      /* the title screen's heading (default "cartwheel") */
  const char *subtitle;   /* a line under it (optional) */
  int max_players;        /* 1..4 (default 1); more than 1 adds the join screen */
  bool shared_screen;     /* every player plays in one shared view (one camera, a scrolling brawler or a co-op
                           * platformer): cw_shell_split draws a single view and cw_shell_player_rect gives each
                           * player the whole canvas */
  bool loading;           /* start on the loading screen until cw_shell_loaded */
  size_t game_save_size;  /* bytes of the game's own save data (cw_shell_game_save) */
  uint16_t game_save_version; /* change it when that layout changes: an older save starts over */
  void (*start)(int players, void *user);   /* Play: the players joined; set the match up */
  void (*quit)(void *user);                 /* Quit to title, from the pause menu */
  void (*sound)(cw_shell_sound s, void *user);
  void (*screen_changed)(cw_shell_screen from, cw_shell_screen to, void *user);
  /* Draws behind the title, join, settings and loading screens and the pause menu (in the shell's own 2D pass,
   * canvas units): the game's backdrop, so these screens are not a dark panel. The shell then dims it lightly
   * and draws the menu over it. NULL: the dark panel. */
  void (*draw_background)(cw_shell_screen screen, cw_vec2 canvas, void *user);
  /* The join screen was opened during play (cw_shell_join_open) and confirmed: the match now has this many
   * players (the highest seat held plus one; see cw_shell_seat_taken for which seats are held). The game adapts
   * its roster; it is not started again. Not called when the screen is cancelled. */
  void (*players_changed)(int players, void *user);
  cw_font font;           /* default: the built-in sans (cw_ui_font_sans) */
  cw_color accent;        /* the selected item's colour (default a warm yellow) */
  void *user;
} ...

typedef struct cw_skin_shading_desc {
  t3_color scatter;    /* colour that scatters furthest under the skin (linear; 1, 0.35, 0.22) */
  float wrap;          /* how far light wraps past the terminator, 0 to 1 (0.55) */
  float translucency;  /* strength of light seen through thin parts from behind, 0 = off (0.35) */
  float distortion;    /* how much the surface normal bends the light seen through (0.25) */
  float power;         /* how tightly the glow gathers toward the light (3) */
  float ambient;       /* translucency that reaches every lit pixel, a softening term (0) */
} cw_skin_shading_desc;

typedef enum {
  CW_CELL_NONE,
  CW_CELL_LOADING,
  CW_CELL_LOADED,
  CW_CELL_ACTIVE,
} cw_cell_state;

typedef struct cw_stream_cell {
  int cx, cz;
  int id;              /* cz * cells_x + cx */
  cw_dvec3 origin;     /* world position of the cell's min corner (y = the stream's origin.y) */
  t3_vec3 local;       /* the same in local coordinates (cw_stream_to_local) */
  cw_res res;          /* its file: READY (or FAILED: the log says why); null without path_format */
  void *data;          /* what on_load returned */
} cw_stream_cell;

typedef struct cw_stream_desc {
  int cells_x, cells_z;      /* grid size (each at most 4096) */
  double cell_size;          /* metres; a power of two keeps origin shifts exact: 512 */
  cw_dvec3 origin;           /* world position of cell (0, 0)'s min corner */
  const char *path_format;   /* "world/c_%d_%d.cell.zst" (cx, cz); NULL = cells without files */
  cw_res_type cell_type;     /* 0 = from the path's extension */
  float load_radius;         /* metres: 1500 */
  float active_radius;       /* metres (<= load_radius): 600 */
  float hysteresis;          /* metres: 0 = cell_size / 4 */
  int max_requests_per_tick; /* 0 = 8 */
  int prepare_per_frame;     /* on_load calls per cw_stream_frame: 0 = 1 */
  int res_lane;              /* cw_res lane of cell files: 0 */
  double rebase_distance;    /* metres: 0 = never move the origin */
  /* callbacks (main thread; any may be NULL) */
  void *(*on_load)(cw_stream *s, const cw_stream_cell *c, void *user);   /* returns the cell's data */
  void (*on_unload)(cw_stream *s, const cw_stream_cell *c, void *user);
  void (*on_activate)(cw_stream *s, const cw_stream_cell *c, void *user);
  void (*on_deactivate)(cw_stream *s, const cw_stream_cell *c, void *user);
  void (*on_rebase)(cw_stream *s, t3_vec3 shift, void *user);            /* before the cells' on_cell_rebase */
  void (*on_cell_rebase)(cw_stream *s, const cw_stream_cell *c, void *user); /* every LOADED / ACTIVE cell, id order */
  /* optional: is on_load's work done (a terrain set's background build: cw_terrain_set_ready)?
   * With wait, finish it now and return true. A cell counts as LOADED only once this says so, and a
   * cell that must activate while still preparing makes the tick wait (a stall). Polled each frame. */
  bool (*cell_ready)(cw_stream *s, const cw_stream_cell *c, bool wait, void *user);
  void *user;
} cw_stream_desc;

typedef struct cw_stream_stats {
  int loading, loaded, active;      /* cells now (active cells are loaded too) */
  uint64_t loads, activations, deactivations, unloads; /* so far */
  int start_cells;                  /* cells the first tick activated (waiting for them: the start position's load) */
  double start_ms;                  /* how long that took (wall clock) */
  int stalls;                       /* later activations that had to wait for their cell (should stay 0) */
  double stall_ms, stall_ms_max;    /* wall clock spent waiting (reported, never fed back) */
  double prepare_ms_max;            /* the longest on_load so far (wall clock) */
  int rebases;
  uint64_t activation_hash;         /* FNV-1a 64 over (tick, cell id, on/off) events */
  uint64_t ticks;
} cw_stream_stats;

typedef struct cw_terrain_hit {
  t3_vec3 point, normal;
  float distance;
  uint32_t control;         /* the control word of the nearest sample */
} cw_terrain_hit;

typedef struct cw_terrain_stats {
  int patches, patches_far;     /* instances drawn: near / far programs */
  int patches_culled;           /* patches the frustum rejected */
  int nodes_visited;
  int levels[CW_TERRAIN_MAX_LODS]; /* patches per level */
  int scatter_cells, scatter_cells_visible, scatter_instances, scatter_draws;
  float select_ms, scatter_ms, upload_ms;
  uint64_t selection_hash;      /* FNV-1a over the selected patches (tests) */
} cw_terrain_stats;

typedef struct cw_scatter_def {
  /* mesh LODs, finest first (a LOD with no part 0 ends the list), each of up to CW_SCATTER_PARTS parts
   * drawn with the same instances (a trunk and a crown: a glTF mesh's primitives); retained */
  t3_geometry *geometry[CW_SCATTER_LODS][CW_SCATTER_PARTS];
  t3_material *material[CW_SCATTER_LODS][CW_SCATTER_PARTS]; /* per part (NULL = the previous LOD's part) */
  float lod_distance[CW_SCATTER_LODS];    /* metres where LOD i + 1 takes over */
  float density;            /* instances per square metre at full density: 0.5 */
  uint32_t layers;          /* control layers it grows on (bit i = layer i; on the base layer, or the
                               overlay where the blend is over half): 0 = all */
  const uint8_t *density_map; /* optional: dm_w x dm_h grey (0..255) over the whole terrain; copied */
  int dm_w, dm_h;
  float min_slope_cos;      /* only where the normal's y is at least this: 0 */
  float scale_min, scale_max; /* uniform scale range: 0.8, 1.2 */
  bool align_to_normal;     /* tilt with the ground (grass, rocks) instead of standing up (trees) */
  float sink;               /* metres pushed into the ground: 0 */
  float visible_range;      /* metres: 60 */
  float fade;               /* metres at the end of visible_range over which instances shrink away: 10 */
  bool cast_shadow;         /* LOD 0 casts (coarser LODs never do): false */
  const char *density_knob; /* cw_quality_scale knob: "grass" (default) or "scatter" */
  uint32_t seed;
} cw_scatter_def;

typedef struct cw_terrain_set_desc {
  cw_terrain_def def;       /* every cell's terrain (origin is per cell) */
  cw_terrain *layers;       /* the template whose layers every cell shares (yours; set its layers first) */
  cw_scatter_def scatter[CW_TERRAIN_SET_SCATTER]; /* each cell's scatter layers (seed ^ cell id * 0x9E3779B1); the set keeps its own references */
  int scatter_count;
  cw_world3d world;         /* physics while active (null: none) */
  cw_shape3d_def shape;     /* the height-field shapes' settings */
} cw_terrain_set_desc;

typedef struct cw_terrain_set_stats {
  int terrains, terrains_drawn, patches, scatter_instances, scatter_draws;
  float update_ms;          /* the pass's CPU time last frame (selection, scatter posing, uploads) */
  float upload_ms;
} cw_terrain_set_stats;

typedef enum {
